const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),crypto=require('node:crypto');
const {execFile}=require('node:child_process');
const {demand,hasSecret}=require('./safety');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function enrich(run,audit,phase){return {...audit,reportId:`${run.id}-${phase}`,phase,date:new Date().toISOString(),client:run.requirements.businessName||run.context.clientId,project:run.context.projectId,website:run.requirements.website||'Not supplied',mode:run.mode,websiteType:run.requirements.websiteType||'Existing site',framework:run.mode==='CREATE_NEW'?run.requirements.framework:audit.framework||'See static audit',currentStatus:run.state,proposedChanges:run.plan.map(p=>({file:p.file,reason:p.reason})),approvedDesign:run.designLock||null,runtime:{evidence:'NOT_MEASURED',render:'NOT MEASURED',navigation:'NOT MEASURED',console:'NOT MEASURED',overflow:'NOT MEASURED',performance:'NOT MEASURED'},limitations:[...(audit.limitations||[]).map(line=>/^Browser layout/.test(line)?'Static analysis alone does not test browser behaviour. See separately labeled runtime measurements when run.':line),'Bounded source inspection; no live crawl, Lighthouse or Core Web Vitals measurement.','Client-supplied content and all placeholders require review before publishing.']};}
function preview(spec,name,mobile=false){if(!spec)return '';const columns=mobile?'1fr':spec.layout==='poster'?'1fr':'1fr 1fr';return `<div class="design-preview" style="background:${esc(spec.background)};color:${esc(spec.ink)}"><small>DESIGN PREVIEW · ${mobile?'MOBILE':'DESKTOP'} · NOT A SITE SCREENSHOT</small><div class="preview-nav">${esc(name)} <span>Overview &nbsp; Services &nbsp; Contact</span></div><div style="display:grid;grid-template-columns:${columns};gap:20px"><div><p>${esc(spec.style)}</p><h3 style="font-size:${mobile?24:34}px">${esc(name)}</h3><p>Approved composition: ${esc(spec.layout)}, ${esc(spec.typography)}</p><strong style="background:${esc(spec.primary)};color:${esc(spec.buttonInk||'#fff')};padding:10px;display:inline-block">${esc(spec.cta)}</strong></div><div style="background:${esc(spec.accent)};min-height:120px;padding:20px">Client imagery area<br>DESIGN PLACEHOLDER</div></div><div class="preview-sections">${spec.sections.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div>`;}
function reportHtml(run,phase){
 demand(['BEFORE','AFTER'].includes(phase),'Invalid report phase',400);const data=phase==='BEFORE'?run.beforeReport:run.afterReport;demand(data,'Report is not available',409);
 const report={...data,proposedChanges:run.plan.map(p=>({file:p.file,reason:p.reason})),approvedDesign:run.designLock||null};
 demand(!hasSecret(JSON.stringify(report)),'Sensitive report withheld');
 const findings=phase==='BEFORE'?report.issues||[]:report.issuesRemaining||report.remainingIssues||[];
 const rows=findings.map(i=>`<tr><td><b>${esc(i.severity)}</b><br><small>${esc(i.evidenceType||'STATIC')}</small></td><td>${esc(i.file)}<br><b>${esc(i.issue||i.recommendation)}</b></td><td>${esc(i.reason)}<br>${esc(i.recommendedFix||i.recommendation)}</td></tr>`).join('');
 const list=values=>`<ul>${(values.length?values:['None recorded.']).map(v=>`<li>${esc(typeof v==='string'?v:v.commandId?`${v.commandId}: ${v.passed?'PASS':'FAIL'} (exit ${v.exitCode})`:v.file?`${v.file}: ${v.reason||v.issue||v.recommendation||'Review required'}`:JSON.stringify(v))}</li>`).join('')}</ul>`;
 const runtime=report.runtime||{}, runtimeTable=runtime.evidence==='MEASURED'?`<p><b>MEASURED:</b> ${esc(runtime.scope)}</p><table><thead><tr><th>Page / width</th><th>Render / overflow</th><th>Navigation</th></tr></thead><tbody>${runtime.pages.map(p=>`<tr><td>${esc(p.file)} / ${p.width}px</td><td>${p.render?'Rendered':'FAILED'} / ${p.horizontalOverflow?'OVERFLOW':'No overflow'}</td><td>${p.navigation.filter(l=>l.status!==null).length} local links; ${p.navigation.filter(l=>l.status>=400).length} HTTP failures</td></tr>`).join('')}</tbody></table><p>Console/runtime errors: ${runtime.errors.length}. Missing resources: ${runtime.missingResources.length}. Performance / Lighthouse / Core Web Vitals: NOT MEASURED.</p>`:'<p>Runtime rendering, navigation and responsive checks: NOT MEASURED. Performance / Lighthouse / Core Web Vitals: NOT MEASURED.</p>';
 const selected=run.designLock?.layoutSpecification;
 const validShot=shot=>shot && typeof shot.data==='string' && shot.data.length<1500000 && /^[A-Za-z0-9+/=]+$/.test(shot.data) && Buffer.from(shot.data,'base64').subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));
 const approvedShots=(run.designVariants||[]).find(v=>v.id===run.designLock?.selectedVariantId)?.renderedPreviews||[];
 const comparison=phase==='AFTER' && run.siteScreenshots?.some(validShot)?`<h2>Approved design / generated-site snapshot</h2><p>MEASURED browser captures in an isolated source snapshot. Design previews show proposed composition; final snapshots show generated content. This is a visual review, not a numerical similarity or performance score.</p>${run.siteScreenshots.filter(validShot).map(shot=>{const approved=approvedShots.find(a=>a.width===shot.width && validShot(a));return `<div class="capture-comparison"><h3>${shot.width}px viewport</h3><div class="capture-grid"><div>${approved?`<p>Approved design preview</p><img alt="Approved design preview" src="data:image/png;base64,${approved.data}">`:'<p>Approved design screenshot NOT CAPTURED. See locked specification above.</p>'}</div><div><p>Generated-site source snapshot</p><img alt="Generated-site browser snapshot" src="data:image/png;base64,${shot.data}"></div></div></div>`;}).join('')}`:phase==='AFTER'?'<h2>Design / generated-site comparison</h2><p>Final-site screenshots NOT CAPTURED. Run isolated browser checks with capture enabled to include a visual comparison.</p>':'';
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:"><title>OneLeadQ ${phase} report</title><style>@page{size:A4;margin:18mm 16mm}*{box-sizing:border-box}body{font:11px/1.6 Arial,sans-serif;color:#20312f;margin:0}header{border-bottom:5px solid #0b5d4b;padding-bottom:18px;margin-bottom:22px}h1{font-size:30px;line-height:1.2;margin:10px 0;color:#0b5d4b}.brand{font-size:20px;font-weight:800;letter-spacing:2px}h2{break-after:avoid;font-size:18px;color:#0b5d4b;border-bottom:1px solid #d4e2dd;padding-bottom:6px;margin-top:16px}h3{line-height:1.15}.meta{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:#edf4f1;padding:14px}.summary{background:#fff4d8;padding:15px;border-left:4px solid #b88927}table{border-collapse:collapse;width:100%;table-layout:fixed}th{text-align:left;background:#0b5d4b;color:#fff;padding:9px}td{padding:9px;vertical-align:top;border-bottom:1px solid #dae2de;overflow-wrap:anywhere}td:first-child{width:20%}tr{break-inside:avoid}thead{display:table-header-group}small{font-size:9px}.design-preview{padding:16px;margin:12px 0;border:1px solid #ccc;break-inside:avoid}.preview-nav{padding-block:12px;display:flex;justify-content:space-between}.preview-sections{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.preview-sections span{border:1px solid currentColor;padding:8px}.capture-comparison{break-inside:avoid;margin-top:18px}.capture-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.capture-grid img{display:block;width:100%;height:380px;object-fit:contain;object-position:top left;border:1px solid #d4e2dd}footer{break-inside:avoid;margin-top:16px;padding-top:10px;border-top:1px solid #ccd8d2;color:#536761}li{margin:5px 0;overflow-wrap:anywhere}</style></head><body><header><div class="brand">OneLeadQ</div><h1>${phase} Website Report</h1><p>Client-reviewed evidence and implementation record</p></header><div class="meta"><div><b>Client</b><br>${esc(report.client||run.context.clientId)}</div><div><b>Project / website</b><br>${esc(run.context.projectId)} / ${esc(run.requirements.website||'Not supplied')}</div><div><b>Date</b><br>${esc(report.date)}</div><div><b>Report number</b><br>${esc(report.reportId)}</div><div><b>Mode / type</b><br>${esc(run.mode)} / ${esc(run.requirements.websiteType||'Existing')}</div><div><b>Framework</b><br>${esc(run.requirements.framework||report.framework)}</div></div><h2>Executive summary</h2><div class="summary">${phase==='BEFORE'?'Source audit and reviewed implementation proposal.':'Implementation and validation evidence.'} ${findings.length} findings remain in this report. All findings are static unless explicitly labeled MEASURED. Performance and live crawl: NOT MEASURED. Runtime snapshot: ${report.runtime?.evidence==='MEASURED'?'MEASURED (see checks below)':'NOT MEASURED'}.</div>${selected?`<h2>Approved design · revision ${run.designLock.revision}</h2><p>Variant ${esc(run.designLock.selectedVariantId)} approved ${esc(run.designLock.approvedAt)}. Screenshot comparisons, when captured, are shown separately below.</p>${preview(selected,run.requirements.businessName)}${preview(selected,run.requirements.businessName,true)}`:''}<h2>Audit findings · SEO, UX and technical priorities</h2><table><thead><tr><th>Priority / evidence</th><th>File / issue</th><th>Reason / recommendation</th></tr></thead><tbody>${rows||'<tr><td colspan="3">No findings recorded in the bounded source inspection. This does not establish a full live-site pass.</td></tr>'}</tbody></table><h2>${phase==='BEFORE'?'Proposed changes':'Implementation summary'}</h2>${list(phase==='BEFORE'?report.proposedChanges:report.filesChanged||[])}${phase==='AFTER'?`<h2>Issues fixed</h2>${list(report.issuesFixed||[])}<h2>Validation results</h2>${list(report.validations||[])}<h2>Git status</h2>${list([report.gitStatus||'Refresh Git review for current status'])}`:''}<h2>Measured checks and pending work</h2>${runtimeTable}${list((report.audit?.assetMetadata||report.assetMetadata||[]).map(a=>`${a.file}: ${a.bytes} bytes (MEASURED FILE METADATA)`))}${comparison}<h2>Limitations and client review</h2>${list(report.limitations||[])}<footer>OneLeadQ · AI proposes. User reviews and approves. Reports do not authorize writes, commits or pushes.</footer></body></html>`;
}
function browserBinary(){return ['C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe','C:/Program Files/Microsoft/Edge/Application/msedge.exe'].find(p=>fs.existsSync(p));}
async function pdf(run,phase){
 const html=reportHtml(run,phase),browser=browserBinary();demand(browser,'PDF rendering is unavailable on this backend. Install the approved local Edge renderer; HTML report remains available.',503);
 const directory=fs.mkdtempSync(path.join(os.tmpdir(),'oneleadq-report-')),input=path.join(directory,'report.html'),output=path.join(directory,'report.pdf');fs.writeFileSync(input,html,'utf8');
 try{await new Promise((resolve,reject)=>execFile(browser,['--headless','--disable-gpu','--no-pdf-header-footer','--disable-extensions','--disable-background-networking',`--user-data-dir=${path.join(directory,'profile')}`,`--print-to-pdf=${output}`,require('node:url').pathToFileURL(input).href],{windowsHide:true,timeout:90000,maxBuffer:100000},error=>error?reject(new Error('PDF rendering failed; no report published')):resolve()));const bytes=fs.readFileSync(output);demand(bytes.subarray(0,5).toString()==='%PDF-','Invalid PDF renderer output',503);return bytes;
 }finally{if(directory.startsWith(path.join(os.tmpdir(),'oneleadq-report-')))try{fs.rmSync(directory,{recursive:true,force:true})}catch{}}
}
module.exports={enrich,preview,reportHtml,pdf,browserBinary};
